{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative (sentiment < 0) or shows recent negative momentum.",
    "Reduce forecast bias by applying a mean-reversion correction to recent over- or under-forecasted periods.",
    "When price spikes occur, apply a lagged correction: reduce forecast by 10-15% of the spike magnitude for the next 3-5 days.",
    "For long-term horizons (>10 days), apply a smoothing filter to reduce volatility and avoid overreaction to short-term noise.",
    "If sentiment is positive and forecast is consistently below true outcome, increase forecast by 5-10% to align with sentiment-driven momentum.",
    "When true outcome is significantly lower than forecast, especially after a spike, apply a ‘recovery lag’ correction: delay upward adjustment by 1-2 days."
  ]
}
